1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUM_BY_ITEM_TYPE = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	  moonstone: 25,
10	} as const satisfies Record<string, number>;
11	
12	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
13	
14	const INSURANCE_VALUE_BY_ITEM_TYPE = {
15	  sword: 1000,
16	  amulet: 600,
17	  staff: 800,
18	  potion: 400,
19	  rune: 250,
20	  moonstone: 250,
21	} as const satisfies Record<InsurableItemType, number>;
22	
23	const DEDUCTIBLE_PER_DAMAGE = 100;
24	
25	// Distinct from HIGH_ENCHANTMENT_THRESHOLD: that one raises the premium at
26	// level 5, this one halves the reimbursement at level 8.
27	const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
28	
29	const REIMBURSEMENT_ENCHANTMENT_RATE = 0.5;
30	
31	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
32	
33	const BLOCK_SIZE = 3;
34	
35	const BLOCK_BASE_PREMIUM = 60;
36	
37	const CURSE_SURCHARGE_RATE = 0.5;
38	
39	const HIGH_ENCHANTMENT_THRESHOLD = 5;
40	
41	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
42	
43	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
44	
45	const LOYALTY_YEARS_THRESHOLD = 2;
46	
47	const LOYALTY_DISCOUNT_RATE = 0.2;
48	
49	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
50	
51	export type QuoteResult = { premium: number };
52	
53	export type ClaimResult = { payout: number; remainingCap: number };
54	
55	export type ScenarioResult = QuoteResult | ClaimResult;
56	
57	export type ScenarioOutcome = { results: ScenarioResult[] };
58	
59	type Item = {
60	  type: InsurableItemType;
61	  cursed?: boolean;
62	  enchantment?: number;
63	};
64	
65	type Customer = { yearsWithMHPCO: number };
66	
67	type QuoteStep = { op: "quote"; items: Item[] };
68	
69	type Damage = { itemType: string; amount: number };
70	
71	type ClaimStep = {
72	  op: "claim";
73	  policy: number;
74	  incident: { cause: string; damages: Damage[] };
75	};
76	
77	type Step = QuoteStep | ClaimStep;
78	
79	type Scenario = { customer: Customer; steps: Step[] };
80	
81	// Amounts are rounded in the MHPCO's favour: premiums (charged to the
82	// customer) round up.
83	const roundPremiumInMHPCOsFavour = (amount: number): number =>
84	  Math.ceil(amount);
85	
86	const countByItemType = (items: Item[]): Map<InsurableItemType, number> => {
87	  const counts = new Map<InsurableItemType, number>();
88	
89	  for (const item of items) {
90	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
91	  }
92	
93	  return counts;
94	};
95	
96	// Exactly 3 alike components form a building block at a special base premium.
97	const basePremiumForAlikeItems = (
98	  type: InsurableItemType,
99	  count: number,
100	): number =>
101	  count === BLOCK_SIZE
102	    ? BLOCK_BASE_PREMIUM
103	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
104	
105	const basePremiumOf = (items: Item[]): number =>
106	  [...countByItemType(items)]
107	    .map(([type, count]) => basePremiumForAlikeItems(type, count))
108	    .reduce((total, premium) => total + premium, 0);
109	
110	const ownBasePremiumOf = (item: Item): number =>
111	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
112	
113	// Item-specific modifiers apply to the affected item's own base premium,
114	// not to the policy total.
115	type ItemModifier = { appliesTo: (item: Item) => boolean; rate: number };
116	
117	const CURSE_MODIFIER: ItemModifier = {
118	  appliesTo: (item) => item.cursed === true,
119	  rate: CURSE_SURCHARGE_RATE,
120	};
121	
122	const HIGH_ENCHANTMENT_MODIFIER: ItemModifier = {
123	  appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
124	  rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
125	};
126	
127	const ITEM_MODIFIERS: ItemModifier[] = [
128	  CURSE_MODIFIER,
129	  HIGH_ENCHANTMENT_MODIFIER,
130	];
131	
132	const itemSurchargeOf = (items: Item[], modifier: ItemModifier): number =>
133	  items
134	    .filter(modifier.appliesTo)
135	    .reduce((total, item) => total + ownBasePremiumOf(item) * modifier.rate, 0);
136	
137	// Item modifiers accumulate: an item matching several of them pays each
138	// surcharge on its own base premium.
139	const itemSurchargesOf = (items: Item[]): number =>
140	  ITEM_MODIFIERS.reduce(
141	    (total, modifier) => total + itemSurchargeOf(items, modifier),
142	    0,
143	  );
144	
145	// Policy-wide modifiers are computed from the policy base premium, so the
146	// first insurance surcharge is 10 % of the base — not of base plus curse.
147	// A modifier's rate is signed: surcharges are positive, discounts negative.
148	type PolicyContext = { customer: Customer; precedingQuotes: number };
149	
150	type PolicyModifier = {
151	  appliesTo: (context: PolicyContext) => boolean;
152	  rate: number;
153	};
154	
155	const FIRST_INSURANCE_MODIFIER: PolicyModifier = {
156	  appliesTo: () => true,
157	  rate: FIRST_INSURANCE_SURCHARGE_RATE,
158	};
159	
160	const LOYALTY_MODIFIER: PolicyModifier = {
161	  appliesTo: ({ customer }) =>
162	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
163	  rate: -LOYALTY_DISCOUNT_RATE,
164	};
165	
166	// Each item in a quote counts as a first insurance regardless of customer
167	// history, so this discount stacks with the first insurance surcharge.
168	const FOLLOW_UP_CONTRACT_MODIFIER: PolicyModifier = {
169	  appliesTo: ({ precedingQuotes }) => precedingQuotes >= 1,
170	  rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
171	};
172	
173	const POLICY_MODIFIERS: PolicyModifier[] = [
174	  FIRST_INSURANCE_MODIFIER,
175	  LOYALTY_MODIFIER,
176	  FOLLOW_UP_CONTRACT_MODIFIER,
177	];
178	
179	// Policy modifiers accumulate: each applicable one is computed on the same
180	// policy base premium, never compounded on top of another.
181	const policyAdjustmentOf = (
182	  basePremium: number,
183	  context: PolicyContext,
184	): number =>
185	  POLICY_MODIFIERS.filter((modifier) => modifier.appliesTo(context)).reduce(
186	    (total, modifier) => total + basePremium * modifier.rate,
187	    0,
188	  );
189	
190	const quotePremium = (items: Item[], context: PolicyContext): number => {
191	  const basePremium = basePremiumOf(items);
192	
193	  return roundPremiumInMHPCOsFavour(
194	    basePremium +
195	      itemSurchargesOf(items) +
196	      policyAdjustmentOf(basePremium, context) +
197	      PROCESSING_FEE,
198	  );
199	};
200	
201	const insuranceSumOf = (items: Item[]): number =>
202	  items.reduce(
203	    (total, item) => total + INSURANCE_VALUE_BY_ITEM_TYPE[item.type],
204	    0,
205	  );
206	
207	// The reimbursement clauses depend on the insured item's attributes, which the
208	// damage entry does not carry — it names only the item type.
209	const reimbursementFor = (damageAmount: number, insuredItem: Item): number =>
210	  (insuredItem.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD
211	    ? damageAmount * REIMBURSEMENT_ENCHANTMENT_RATE
212	    : damageAmount;
213	
214	// A deductible applies per damage event, i.e. once per damaged item.
215	const payoutForDamage = (damage: Damage, insuredItems: Item[]): number => {
216	  const insuredItem = insuredItems.find(
217	    (item) => item.type === damage.itemType,
218	  ) as Item;
219	
220	  return reimbursementFor(damage.amount, insuredItem) - DEDUCTIBLE_PER_DAMAGE;
221	};
222	
223	// A policy is created by a quote step; claims draw down its remaining cap.
224	// The insured items are retained because payout clauses depend on them.
225	type Policy = { remainingCap: number; items: Item[] };
226	
227	const capFor = (items: Item[]): number =>
228	  insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
229	
230	// A claim quotes its policy by the index of the step that created it, so
231	// policies are keyed by that index rather than collected in a list.
232	type ScenarioState = {
233	  customer: Customer;
234	  policiesByStep: Map<number, Policy>;
235	  precedingQuotes: number;
236	  results: ScenarioResult[];
237	};
238	
239	const initialState = (customer: Customer): ScenarioState => ({
240	  customer,
241	  policiesByStep: new Map(),
242	  precedingQuotes: 0,
243	  results: [],
244	});
245	
246	// Each step handler folds the state forward: it reads what earlier steps
247	// established and returns the state the following steps will see.
248	const applyQuote = (
249	  state: ScenarioState,
250	  step: QuoteStep,
251	  stepIndex: number,
252	): ScenarioState => {
253	  const { customer, precedingQuotes } = state;
254	  const premium = quotePremium(step.items, { customer, precedingQuotes });
255	
256	  return {
257	    ...state,
258	    policiesByStep: new Map(state.policiesByStep).set(stepIndex, {
259	      remainingCap: capFor(step.items),
260	      items: step.items,
261	    }),
262	    precedingQuotes: precedingQuotes + 1,
263	    results: [...state.results, { premium }],
264	  };
265	};
266	
267	const applyClaim = (state: ScenarioState, step: ClaimStep): ScenarioState => {
268	  const policy = state.policiesByStep.get(step.policy) as Policy;
269	  const payout = step.incident.damages.reduce(
270	    (total, damage) => total + payoutForDamage(damage, policy.items),
271	    0,
272	  );
273	  const remainingCap = policy.remainingCap - payout;
274	
275	  return {
276	    ...state,
277	    policiesByStep: new Map(state.policiesByStep).set(step.policy, {
278	      ...policy,
279	      remainingCap,
280	    }),
281	    results: [...state.results, { payout, remainingCap }],
282	  };
283	};
284	
285	const applyStep = (
286	  state: ScenarioState,
287	  step: Step,
288	  stepIndex: number,
289	): ScenarioState =>
290	  step.op === "quote"
291	    ? applyQuote(state, step, stepIndex)
292	    : applyClaim(state, step);
293	
294	export const runScenario = (scenario: unknown): ScenarioOutcome => {
295	  const { customer, steps } = scenario as Scenario;
296	
297	  const { results } = steps.reduce(applyStep, initialState(customer));
298	
299	  return { results };
300	};
